export default {
  version: 1,
  name: "Brass Prop Step",
  description: "A stationary prop glows brass while the courier is within 90 units. A solid step appears to its right, 32 units above its feet. The step lasts one tick and is renewed only while the courier remains nearby, so it expires when the courier moves away.",
  rules: [
    {
      id: "nearby-stationary-prop-step",
      each: "prop",
      when: {
        all: [
          { compare: { left: { field: "speed" }, op: "eq", right: 0 } },
          { compare: { left: { field: "distanceToPlayer" }, op: "lte", right: 90 } }
        ]
      },
      actions: [
        { type: "createSurface", offsetX: 56, offsetY: -32, width: 72, lifetime: 1, solid: true },
        { type: "cue", target: "self", color: "brass", intensity: 0.8 }
      ]
    }
  ]
} satisfies RuleModule;
